import {enableManualFines, assessFine, quickPayment, undoPayment, normalizeName, parseOrderedNames, resolveManualOrder, applyManualOrder, parseNames, chooseIndex, cents, money, localNow, deadline, schedule, obligation, periodTotals, groupTotals, validatePayment, validatePayout} from './engine.js';
import {openReport} from './report.js';
import {cloudInfo,configure,login,logout,readRemote,writeRemote,probeConnection} from './cloud.js';
import {createAutoSync} from './auto-sync.js';
const $=id=>document.getElementById(id);
const escape=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const uid=()=>crypto.randomUUID();
const validId = id => typeof id === 'string' && /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(id);
const storageKey='pasanaku-digital-v2';
const emptyDB=()=>({schema:2,groups:[],active:null});
const deviceKey='pasanaku-device-v3';
let db=emptyDB(),storageProblem=false,deviceRaw=null,syncDoc=null,sync,tabStale=false;
try {
 deviceRaw=localStorage.getItem(deviceKey);
 if(deviceRaw) {
   syncDoc=JSON.parse(deviceRaw);validateBackup(syncDoc.data);
   if((syncDoc.owner!==null&&typeof syncDoc.owner!=='string') || (syncDoc.version!==null&&(!Number.isSafeInteger(syncDoc.version)||syncDoc.version<0)) || typeof syncDoc.dirty!=='boolean') throw Error('Metadatos de guardado inválidos.');
   db=syncDoc.data;
 } else {
   const saved=JSON.parse(localStorage.getItem(storageKey)||'null');
   if(saved){validateBackup(saved);db=saved;}
 }
} catch {syncDoc=null;storageProblem=true;}
syncDoc ||= {data:db,owner:null,version:null,dirty:db.groups.length>0};
let view='overview',periodId=null,search='',spinning=false,angle=0,toastTimer;
const routes=[['overview','Inicio','grid'],['payments','Pagos','wallet'],['calendar','Turnos','calendar'],['people','Grupo','users'],['draw','Organizar turnos','wheel'],['fines','Multas','clock'],['reports','Resumen y PDF','file'],['settings','Ajustes y respaldo','file']];
const group=()=>db.groups.find(g=>g.id===db.active);
const person=(g,id)=>g.people.find(p=>p.id===id);
const selected=g=>g.periods.find(p=>p.id===periodId)||g.periods.find(p=>!p.payout)||g.periods.at(-1);
const formatDate=(date,options={day:'numeric',month:'short',year:'numeric'})=>new Intl.DateTimeFormat('es-BO',{...options,timeZone:'America/La_Paz'}).format(new Date(date.includes('T')?date:date+'T12:00:00-04:00'));
const initials=name=>name.split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const avatar=(name,i=0)=>`<span class="avatar" style="background:${['#eaf0df','#e9edf5','#f8eddf','#eee9f5'][i%4]}">${escape(initials(name))}</span>`;
const button=(text,action,style='primary',attributes='')=>`<button class="button ${style}" data-action="${action}" ${attributes}>${text}</button>`;
const pill=(text,type='')=>`<span class="pill ${type}">${escape(text)}</span>`;
const empty=(title,text,action='')=>`<div class="empty"><span class="empty-icon">${icon('users')}</span><h3>${title}</h3><p>${text}</p>${action}</div>`;
function notify(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function persist(){sync.commit(db);storageProblem=false;}
function change(fn,text){if(tabStale){notify('Recarga esta pestaña antes de registrar cambios.');return false;}if(storageProblem&&!pendingImport){notify('Recupera un respaldo desde Respaldo y conexión antes de reemplazar datos que no se pudieron leer.');return false;}const before=structuredClone(db);try{for(const g of db.groups)enableManualFines(g);fn();for(const g of db.groups)enableManualFines(g);persist();render();if(text)notify(text);return true;}catch(error){db=before;const message=error.name==='QuotaExceededError'?'No se pudo guardar. Descarga un respaldo y libera espacio antes de continuar.':error.message;const node=$('modal').open?$('modal-content').querySelector('.form-error'):null;if(node)node.textContent=message;else notify(message);return false;}}
const audit=(g,text)=>g.audit.push({id:uid(),at:new Date().toISOString(),text});
function showModal(content,locked=false){$('modal-content').innerHTML=content;$('close-modal').hidden=locked;$('modal').dataset.locked=locked?'true':'false';if(!$('modal').open)$('modal').showModal();}
function closeModal(){if($('modal').dataset.locked!=='true')$('modal').close();}
$('close-modal').onclick=closeModal;
$('modal').addEventListener('cancel',event=>{if($('modal').dataset.locked==='true')event.preventDefault();});
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">JUNTOS, TURNO A TURNO</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function groupBar(g){return `<div class="group-bar"><label class="select-group-label" for="group-select">Seleccionar grupo</label><select id="group-select" aria-label="Seleccionar grupo">${db.groups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${escape(x.name)}</option>`).join('')}</select>${pill(g.periods.every(p=>p.payout)?'Ciclo entregado':g.assignment==='manual'?'Orden acordado':g.order.length===g.people.length?'Sorteo completo':g.order.length?'Sorteo en curso':'Listo para sortear',g.order.length===g.people.length?'':'neutral')}</div>`;}
function stat(label,value,note,ic,accent=''){return `<div class="stat ${accent}"><div class="stat-head">${label}${icon(ic)}</div><strong>${value}</strong><small>${note}</small></div>`;}
function periodSelect(g,id='period-select'){const p=selected(g);return `<select id="${id}" aria-label="Seleccionar turno">${g.periods.map((r,i)=>`<option value="${r.id}" ${r.id===p.id?'selected':''}>Turno ${i+1} · ${escape(formatDate(r.date))}</option>`).join('')}</select>`;}
function setupHero(){return `<section class="hero"><div><div class="eyebrow">MENOS CUENTAS. MÁS TRANQUILIDAD.</div><h2>Tu pasanaku,<br>en buenas manos.</h2><p>Organiza los turnos, registra los aportes y mantén las cuentas claras. Todo en un solo lugar.</p>${button('＋ Crear mi primer pasanaku','create')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="coin">Bs</span></div><span class="leaf">❧</span></div></section>`;}
function overview(g){
 if(!g)return heading('Tu pasanaku, más fácil.','Un grupo, un calendario y los pagos al día.')+setupHero();
 const p=selected(g),t=periodTotals(g,p),who=person(g,p.person);
 return heading('Todo listo para tu grupo.','Lleva los pagos al día, sin complicaciones.',button('＋ Nuevo grupo','create','secondary'))+groupBar(g)+`<section class="hero simple-hero"><div><div class="eyebrow">TURNO ${g.periods.indexOf(p)+1} DE ${g.people.length} · ${escape(formatDate(p.date))}</div><h2>${who?escape(who.name)+' recibe este turno':'Organicemos el primer turno'}</h2><p>${who?money(g.amount*g.people.length)+' entre '+g.people.length+' personas. Cada una aporta '+money(g.amount)+'.':'Puedes usar la ruleta o ingresar el orden que ya acordaron.'}</p><button class="button primary" data-view="${who?'payments':'draw'}">${who?'Registrar pagos':'Organizar turnos'} ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="coin">Bs</span></div></div></section><div class="stats simple-stats">${stat('Ya pagaron',t.complete+' de '+g.people.length,'En este turno','users')}${stat('Falta reunir',money(t.owed),'Para completar el fondo','wallet')}${stat('Multas pendientes',money(t.fineOwed),'Marcadas por el administrador','clock')}</div><section class="card"><div class="card-heading"><h2>Las próximas fechas</h2><button class="link-button" data-view="calendar">Ver todos los turnos ${icon('arrow')}</button></div>${calendarTable(g,4)}</section>`;
}
function calendarTable(g,limit=g.periods.length){return `<div class="table-wrap"><table><thead><tr><th>Turno</th><th>Fecha de entrega</th><th>Participante</th><th>Fondo</th><th>Estado</th></tr></thead><tbody>${g.periods.slice(0,limit).map((p,i)=>`<tr><td><span class="tag-number">${String(i+1).padStart(2,'0')}</span></td><td>${escape(formatDate(p.date))}</td><td>${escape(person(g,p.person)?.name||'Por sortear')}</td><td>${money(g.amount*g.people.length)}</td><td>${pill(p.payout?'Entregado':p.person?'Asignado':'Por sortear',p.payout?'':p.person?'warning':'neutral')}</td></tr>`).join('')}</tbody></table></div>`;}
function peoplePage(g){return heading('Tu grupo.','Cada persona recibe una vez y sigue aportando hasta el final.')+groupBar(g)+`<section class="card"><div class="card-heading"><h2>${g.people.length} participantes</h2><button class="link-button" data-view="draw">Organizar turnos ${icon('arrow')}</button></div><ul class="mini-list group-people">${g.people.map((who,i)=>{const turn=g.periods.find(p=>p.person===who.id);return `<li>${avatar(who.name,i)}<div><strong>${escape(who.name)}</strong><small>${turn?'Recibe el '+escape(formatDate(turn.date)):'Turno por asignar'}</small></div></li>`;}).join('')}</ul></section><details class="card"><summary>Ver los acuerdos del grupo</summary><p>Aporte: ${money(g.amount)} por persona y turno. Multa: ${money(g.fine)}, solo cuando la marques.</p><p>${escape(g.agreement||'Todos siguen aportando después de recibir.')}<br>Multas: ${escape(g.fundDestination)}</p></details>`;}
function calendarPage(g){const current=selected(g);return heading('Cada turno, en su fecha.','El calendario completo de tu pasanaku, desde el primero hasta el último.','<div class="actions"><button class="button secondary" data-view="draw">Organizar turnos</button>'+button(icon('file')+' PDF','report-all','secondary')+'</div>')+groupBar(g)+`<div class="timeline">${g.periods.map((p,i)=>{const t=periodTotals(g,p);return `<section class="turn-card ${p.id===current.id?'current':''}"><div class="turn-head"><span class="tag-number">${String(i+1).padStart(2,'0')}</span>${pill(p.payout?'Entregado':t.owed?'Aportes pendientes':'Fondo completo',p.payout?'':t.owed?'neutral':'')}</div><div class="turn-date">${escape(formatDate(p.date))}</div><div class="person-name">${escape(person(g,p.person)?.name||'Beneficiario por sortear')}</div><p>${money(g.amount*g.people.length)} · ${t.complete}/${g.people.length} aportes completos</p><button class="button secondary full-width" data-action="turn" data-id="${p.id}">Ver este turno ${icon('arrow')}</button></section>`;}).join('')}</div>`;}
function drawPage(g){
 const remaining=g.people.filter(p=>!g.order.includes(p.id)), next=g.periods[g.order.length], manual=g.assignment==='manual';
 const canImport=!g.order.length&&!g.pending&&!g.periods.some(p=>p.person||p.payout)&&!spinning;
 return heading(manual?'Un orden acordado entre todos.':'Cada persona tiene su turno.',manual?'Registraste la lista del grupo sin sorteo. Las fechas ya están asignadas.':'Sortea con las mismas posibilidades para todos o ingresa el orden que ya acordaron.',canImport?button('Ya tengo el orden','manual-order','secondary'):'')+groupBar(g)+`<div class="wheel-layout"><section class="card wheel-panel">${manual?empty('El calendario está listo.','Cada persona recibirá el fondo en la fecha de su turno. Todos siguen aportando hasta el final.','<button class="button primary" data-view="calendar">Ver calendario '+icon('arrow')+'</button>'):`<div class="wheel-stage"><div class="pointer" aria-hidden="true"></div><canvas id="wheel" width="900" height="900" aria-label="Ruleta de participantes pendientes"></canvas><div class="wheel-center" aria-hidden="true">✳</div></div>${button(icon('wheel')+(g.pending?' Ver resultado pendiente':remaining.length?' Girar la ruleta':' Sorteo completo'),g.pending?'pending':'spin','primary',remaining.length&&!spinning?'':'disabled')}<p>${remaining.length} participantes pendientes ${next?'· Turno '+(g.order.length+1)+' · '+escape(formatDate(next.date)):''}</p>`}</section><div><section class="card"><div class="card-heading"><h2>El orden de los turnos</h2>${pill(g.order.length+' de '+g.people.length,'neutral')}</div>${g.order.length?`<ul class="mini-list">${g.order.map((id,i)=>`<li><span class="tag-number">${i+1}</span><div><strong>${escape(person(g,id)?.name)}</strong><small>${escape(formatDate(g.periods[i].date))}</small></div></li>`).join('')}</ul>`:empty('El primer turno te espera.','Usa la ruleta o pulsa «Ya tengo el orden» para pegar la lista acordada.')}</section>${manual?`<div class="notice"><p>Este orden fue <strong>ingresado por el administrador</strong> según el acuerdo del grupo. Quedó registrado en el historial y en los reportes.</p></div>`:`<div class="notice"><p>El resultado se guarda <strong>antes de la animación</strong>. Recargar la página no permite volver a sortearlo. Al aceptar, el turno queda asignado en el calendario.</p></div><section class="card"><h2>Cómo se elige</h2><p>Se usa el generador criptográfico del navegador y una selección uniforme entre los nombres restantes. La ruleta se detiene en el resultado guardado.</p><p class="subtext">El historial permite revisar las asignaciones. Esta versión no es una certificación externa del sorteo.</p></section>`}</div></div>`;
}
function manualOrderModal(){
 const g=group();
 if(g.order.length||g.pending)throw Error('Solo puedes ingresar la lista antes de asignar el primer turno.');
 showModal(`<h2>Ingresa el orden acordado</h2><p>Pega los ${g.people.length} nombres del grupo, uno por línea: primero quien recoge antes, después quien sigue. Puedes usar una lista numerada.</p><form id="manual-order-form" data-group="${g.id}"><div class="field"><label for="manual-names">Lista en orden de cobro</label><textarea id="manual-names" name="names" required placeholder="Ingresa los nombres aquí…"></textarea><small>Usa los nombres registrados en Participantes. No incluyas fechas ni montos.</small></div><p class="subtext">La primera persona recibirá el ${escape(formatDate(g.periods[0].date))}. Las siguientes recibirán en las fechas del calendario actual.</p><p class="form-error" role="alert"></p><div class="form-actions"><button class="button primary" type="submit">Revisar orden y fechas ${icon('arrow')}</button></div></form>`);
}
function previewManualOrder(form){
 const g=group();if(g.id!==form.dataset.group)throw Error('El grupo cambió. Vuelve a abrir la lista.');
 const order=resolveManualOrder(g,new FormData(form).get('names'));
 // Validate without changing the live group until the administrator confirms.
 applyManualOrder(structuredClone(g),order);
 showModal(`<h2>Revisa el orden y las fechas</h2><p>Se guardará como un acuerdo del grupo, sin realizar un sorteo. Una vez confirmado, los turnos quedan fijados.</p><ol class="mini-list">${order.map((id,i)=>`<li><span class="tag-number">${i+1}</span><div><strong>${escape(person(g,id).name)}</strong><small>${escape(formatDate(g.periods[i].date))}</small></div></li>`).join('')}</ol><form id="confirm-order-form" data-group="${g.id}"><input type="hidden" name="order" value="${escape(JSON.stringify(order))}"><p class="form-error" role="alert"></p><div class="form-actions">${button('Corregir lista','edit-manual-order','secondary','type="button"')}<button class="button primary" type="submit">Confirmar este orden</button></div></form>`);
}
function submitManualOrder(form){
 const g=group();if(g.id!==form.dataset.group)throw Error('El grupo cambió. Vuelve a abrir la lista.');
 const order=JSON.parse(new FormData(form).get('order'));
 if(change(()=>{applyManualOrder(g,order);audit(g,'Orden acordado ingresado por el administrador, sin sorteo: '+order.map((id,i)=>`${i+1}. ${person(g,id).name} (${g.periods[i].date})`).join('; ')+'.');},'Orden guardado. Todas las fechas están asignadas.'))$('modal').close();
}
function statusBadge(o){return o.owed?pill(o.principal?'Abono parcial':o.late?'Vencido':'Pendiente',o.late?'red':'warning'):pill(o.fineOwed?'Aporte completo · debe multa':'Al día',o.fineOwed?'warning':'');}
function paymentRows(g,p){const people=g.people.filter(who=>normalizeName(who.name).includes(normalizeName(search)));return people.length?people.map((who,i)=>{
 const o=obligation(g,p,who),attrs=`data-person="${who.id}" data-period="${p.id}"`;
 const last=g.payments.filter(r=>r.period===p.id&&r.person===who.id&&r.principal&&!r.voided).at(-1);
 const fineRecord=g.fineAssessments?.find(r=>r.period===p.id&&r.person===who.id&&!r.voided);
 return `<article class="pay-person ${!o.owed?'is-paid':''}" aria-label="Pagos de ${escape(who.name)}"><div class="pay-person-head">${avatar(who.name,i)}<div><h3>${escape(who.name)}</h3><p>${p.person===who.id?'Recibe el fondo este turno · ':''}${!o.owed?'Aporte completo':o.principal?'Falta '+money(o.owed):'Aporte de '+money(g.amount)}</p></div>${pill(!o.owed?'✓ Pagado':'Pendiente',!o.owed?'':'neutral')}</div><div class="pay-person-actions">${o.owed?button('Registrar pago · '+money(o.owed),'quick-pay','primary',attrs):`<span class="paid-label">${icon('wallet')} ${money(o.principal)} registrados</span>${last&&!p.payout?button('Deshacer pago','quick-undo','secondary small',`data-id="${last.id}"`):''}`}</div><div class="pay-person-fine">${o.fine?`<span class="fine-caption">${o.fineOwed?'Debe multa: '+money(o.fineOwed):'✓ Multa pagada: '+money(o.finePaid)}</span><div class="actions">${o.fineOwed?button('Cobrar multa','quick-fine-pay','soft small',attrs):(()=>{const r=g.payments.filter(r=>r.period===p.id&&r.person===who.id&&r.fine&&!r.voided).at(-1);return r?button('Deshacer cobro','quick-undo','secondary small',`data-id="${r.id}"`):'';})()}${!o.finePaid&&fineRecord?button('Quitar multa','quick-fine-remove','secondary small',attrs):''}</div>`:o.waiver?'<span class="subtext">Multa perdonada</span>':g.fine?button('Aplicar multa · '+money(g.fine),'quick-fine','link-button',attrs):'<span class="subtext">Sin multas acordadas</span>'}</div></article>`;
 }).join(''):empty('No encontramos ese nombre.','Prueba con otro nombre del grupo.');}
function paymentsPage(g){const p=selected(g),t=periodTotals(g,p),who=person(g,p.person);return heading('¿Quién ya pagó?','Elige el turno y marca los pagos que recibiste.')+groupBar(g)+`<div class="toolbar">${periodSelect(g)}<input id="search" type="search" aria-label="Buscar participante" placeholder="Buscar un nombre…" value="${escape(search)}"></div><section class="payment-summary"><div><span>Turno ${g.periods.indexOf(p)+1} · ${escape(formatDate(p.date))}</span><h2>${who?'Recibe '+escape(who.name):'Falta asignar quién recibe'}</h2><p>${t.complete} de ${g.people.length} personas ya pagaron</p></div><div class="payment-summary-amount"><strong>${money(t.principal)}</strong><span>de ${money(g.amount*g.people.length)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${t.principal/(g.amount*g.people.length)*100}%"></div></div></section><p class="payment-help">Marca el pago después de recibir el dinero. Si alguien se atrasó, pulsa «Aplicar multa». Las multas no se generan automáticamente.</p><div id="payment-rows" class="payment-cards">${paymentRows(g,p)}</div><section class="card delivery-card"><div><h2>${p.payout?'✓ Fondo entregado':'Entrega del fondo'}</h2><p>${p.payout?'Entrega registrada para '+escape(who?.name):t.owed?'Falta reunir '+money(t.owed)+' para completar el fondo.':who?money(g.amount*g.people.length)+' listos para '+escape(who.name)+'.':'Asigna un turno antes de registrar la entrega.'}</p></div>${button(p.payout?'Entregado':'Marcar fondo entregado','payout',p.payout?'soft':'primary',p.payout||!who||t.owed?'disabled':'')}</section><details class="card"><summary>Ver pagos registrados</summary>${movementTable(g,p)}</details><div class="actions">${button(icon('file')+' Descargar resumen / PDF','report-period','secondary')}<button class="button secondary" data-view="fines">Ver fondo de multas</button></div>`;}
function movementTable(g,p){const records=g.payments.filter(r=>r.period===p.id).slice().reverse();return records.length?`<ul class="mini-list">${records.map(r=>`<li><div><strong>${escape(person(g,r.person)?.name)} · ${money(r.principal+r.fine)}</strong><small>${r.principal?'Aporte':'Multa'} · ${escape(formatDate(r.at))}${r.voided?' · Deshecho':''}${!r.quick?' · '+escape(r.method):''}</small></div>${!r.voided?button('Deshacer','quick-undo','secondary small',`data-id="${r.id}"`):''}</li>`).join('')}</ul>`:empty('Todavía no hay pagos.','Marca el primer pago en la lista de arriba.');}
function finesPage(g){const tot=groupTotals(g),debts=[];for(const p of g.periods)for(const person of g.people){const o=obligation(g,p,person);if(o.fine||o.waiver)debts.push({p,person,o});}return heading('Un fondo, con propósito.','Revisa las multas cobradas y el dinero disponible.')+groupBar(g)+`<div class="stats">${stat('Multas marcadas',money(tot.fine),'Decididas por el administrador','clock')}${stat('Multas cobradas',money(tot.finePaid),'Dinero realmente recibido','wallet')}${stat('Por cobrar',money(tot.fine-tot.finePaid),'No forma parte de la caja','file')}${stat('Fondo disponible',money(tot.finePaid-tot.fineUsed),'Cobrado menos utilizado','grid','accent')}</div><div class="notice">${icon('users')}<p><strong>Destino acordado:</strong> ${escape(g.fundDestination)}<br>Multa fija: ${money(g.fine)} por persona y turno, solo cuando el administrador la marca. Las condonaciones exigen un motivo y quedan en el historial.</p></div><section class="card"><div class="card-heading"><h2>Detalle de multas</h2></div>${debts.length?`<div class="table-wrap"><table><thead><tr><th>Persona</th><th>Turno</th><th>Aplicada</th><th>Pagada</th><th>Pendiente</th><th>Acción</th></tr></thead><tbody>${debts.map(({p,person,o})=>`<tr><td>${escape(person.name)}</td><td>${g.periods.indexOf(p)+1}<small>${escape(formatDate(p.date))}</small></td><td>${money(o.fine)}</td><td>${money(o.finePaid)}</td><td>${money(o.fineOwed)}</td><td>${o.waiver?pill('Condonada','neutral'):`${button('Cobrar multa','quick-fine-pay','soft small',`data-person="${person.id}" data-period="${p.id}"`)} ${button('Condonar','waive','secondary small',`data-person="${person.id}" data-period="${p.id}" ${o.finePaid?'disabled':''}`)}`}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin multas por ahora.','Las multas que marques en Pagos aparecerán aquí.')}</section><section class="card"><div class="card-heading"><h2>Uso del fondo de multas</h2>${button('＋ Registrar uso','fund-use','primary small',tot.finePaid<=tot.fineUsed?'disabled':'')}</div>${g.fundUses.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Destino y motivo</th><th>Monto</th></tr></thead><tbody>${g.fundUses.map(r=>`<tr><td>${escape(formatDate(r.at))}</td><td>${escape(r.reason)}</td><td>${money(r.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('El fondo sigue intacto.','Registra aquí su distribución o el gasto que el grupo acuerde. Los aportes de los turnos no se mezclan con este fondo.')}</section>`;}
function reportsPage(g){return heading('Las cuentas, a la vista.','Un resumen sencillo para revisar y compartir con tu grupo.')+groupBar(g)+`<section class="card"><div class="report-options"><div class="report-box">${icon('calendar')}<h2>Resumen de un turno</h2><p>Aportes de cada persona, abonos, multas, saldo pendiente y entrega del fondo. Úsalo para tu cierre semanal o mensual.</p>${periodSelect(g)}<br><br>${button(icon('file')+' Preparar PDF del turno','report-period')}</div><div class="report-box">${icon('file')}<h2>Resumen del ciclo completo</h2><p>Calendario de turnos, todas las cuotas, multas, desembolsos y uso del fondo. Incluye acuerdos y registro de cambios.</p><br>${button(icon('file')+' Preparar PDF del ciclo','report-all','secondary')}</div></div><p class="subtext" style="margin-top:20px">Se muestra un informe listo para imprimir. Pulsa «Imprimir / Guardar como PDF» y elige «Guardar como PDF». No se envía automáticamente a nadie.</p></section><section class="card"><div class="card-heading"><h2>Historial de administración</h2>${button('Descargar respaldo','backup','secondary small')}</div>${g.audit.slice().reverse().map(a=>`<div class="audit-line">${escape(a.text)}<small>${escape(localNow(new Date(a.at)).replace('T',' '))} · ${escape(g.admin)}</small></div>`).join('')}</section>`;}
function settingsPage(g){const c=cloudInfo();return heading('Ajustes y respaldo.','Tu conexión y una copia de tus datos, cuando lo necesites.')+(g?'<div class="actions secondary-tools"><button class="button secondary" data-view="reports">Resumen y PDF</button><button class="button secondary" data-view="fines">Fondo de multas</button></div>':'')+`<div class="notice ${storageProblem?'warning':''}">${icon('file')}<p><strong>${storageProblem?'No se pudo leer el guardado local. No registres cambios hasta recuperar un respaldo.':c.connected?'Guardado automático activado.':'Guardado en este dispositivo.'}</strong> Los datos actuales están en este navegador. ${c.connected?'Cada cambio se guarda automáticamente en Supabase. Si no hay conexión, queda pendiente en este dispositivo.':'Inicia sesión para activar el guardado automático en Supabase.'} Descarga respaldos periódicos.</p></div><div class="grid-two"><section class="card"><h2>Un respaldo que puedes llevar contigo</h2><p>Incluye todos tus grupos, acuerdos, turnos, pagos e historial. Guárdalo en un lugar privado.</p><div class="actions">${button('↓ Descargar respaldo','backup')}${button('Restaurar respaldo','import','secondary')}</div><div class="divider"></div><h2>Tu conexión a Supabase</h2><p>Tu proyecto Pasanaku Digital ya está configurado. ${c.connected?'Tu sesión está activa. Tus grupos y movimientos se sincronizan automáticamente.':'Inicia sesión para cargar tus datos y guardarlos automáticamente.'}</p>${button('Verificar conexión','cloud-probe','secondary small')}<br><br><details><summary>Cambiar conexión (avanzado)</summary><br><form id="config-form"><div class="field"><label for="cloud-url">URL del proyecto</label><input id="cloud-url" type="url" required placeholder="https://tu-proyecto.supabase.co" value="${escape(c.url||'')}"></div><br><div class="field"><label for="cloud-key">Clave pública (publishable o anon)</label><input id="cloud-key" required type="password" autocomplete="off" value="${escape(c.key||'')}" placeholder="sb_publishable_…"><small>Nunca ingreses service_role ni claves secretas.</small></div><div class="form-actions"><button class="button secondary" type="submit">Guardar configuración</button></div><p class="form-error" id="config-error"></p></form></details></section><section class="card"><h2>Acceso del administrador</h2>${c.connected?`<p>Sesión de ${escape(c.email)}.</p><p id="cloud-status" aria-live="polite">${escape(sync?.status().message||'Comprobando tu copia…')}</p><div class="actions">${button('Revisar copia de la nube','cloud-load','secondary')}${button('Sincronizar ahora','cloud-push')}</div><br>${button('Cerrar sesión','logout','secondary small')}<p class="subtext" style="margin-top:18px">No necesitas pulsar ningún botón después de registrar cambios. Si aparece un conflicto, descarga un respaldo de tus cambios locales antes de cargar la copia de la nube.</p>`:`<p>Usa un usuario administrador creado en tu proyecto Supabase. Cada cuenta tiene su propio espacio privado.</p><form id="login-form"><div class="field"><label for="email">Correo</label><input id="email" type="email" required autocomplete="username"></div><br><div class="field"><label for="password">Contraseña</label><input id="password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="button primary" type="submit">Iniciar sesión</button></div><p class="form-error" id="login-error"></p></form>`}<div class="divider"></div><h2>Reglas de este grupo</h2>${g?`<p><strong>${escape(g.name)}</strong> · Administra ${escape(g.admin)}<br>${escape(g.agreement)}<br>Multas: ${escape(g.fundDestination)}</p>${button('Eliminar grupo sin iniciar','delete-group','danger small',g.order.length||g.pending||g.payments.length||g.fundUses.length||g.fineAssessments?.length?'disabled':'')}`:'<p>Crea tu primer grupo para definir sus acuerdos.</p>'}</section></div>`;}
function render(){
 const g=group();$('navigation').innerHTML=routes.filter(r=>['overview','payments','calendar','people'].includes(r[0])).map(([key,label,ic])=>`<button class="nav-link ${view===key?'active':''}" data-view="${key}">${icon(ic)}${label}</button>`).join('');
 $('breadcrumb').textContent=`${g?.name||'Mi pasanaku'} / ${routes.find(r=>r[0]===view)?.[1]}`;
 $('today').textContent=formatDate(localNow().slice(0,10),{weekday:'short',day:'numeric',month:'long'});
 updateSyncUI();
 if(!g && view!=='settings')$('main').innerHTML=view==='overview'?overview():heading(routes.find(r=>r[0]===view)?.[1]||'Tu pasanaku','Primero definamos tu grupo y sus acuerdos.')+setupHero();
 else $('main').innerHTML=({overview,people:peoplePage,draw:drawPage,calendar:calendarPage,payments:paymentsPage,fines:finesPage,reports:reportsPage,settings:settingsPage}[view])(g);
 if(view==='draw'&&g)drawWheel(g,angle);
}
function createGroup(){showModal(`<div class="eyebrow">EMPECEMOS</div><h2>Un nuevo pasanaku</h2><form id="group-form"><input type="hidden" name="admin" value="Administrador"><input type="hidden" name="time" value="18:00"><input type="hidden" name="fundDestination" value="Según acuerdo del grupo"><input type="hidden" name="agreement" value="Todos siguen aportando hasta el último turno."><div class="form-grid"><div class="field full"><label for="group-name">Nombre del grupo</label><input id="group-name" name="name" maxlength="70" required placeholder="Ej. Entre amigos"></div><div class="field full"><label for="names">Participantes · uno por línea</label><textarea id="names" name="names" required placeholder="Ingresa los nombres aquí…"></textarea></div><div class="field full"><label for="assignment">Orden de los turnos</label><select id="assignment" name="assignment"><option value="draw">Vamos a sortearlo</option><option value="manual">Ya tengo el orden acordado</option></select><small>Si ya tienen el orden, escribe los nombres en ese orden: primero quien cobra antes.</small></div><div class="field"><label for="amount">Aporte por persona (Bs)</label><input id="amount" name="amount" type="number" min="0.01" max="1000000" step="0.01" required placeholder="200"></div><div class="field"><label for="fine">Multa acordada (Bs)</label><input id="fine" name="fine" type="number" min="0" max="1000000" step="0.01" value="0" required><small>La marcas tú. Cero para no usar multas.</small></div><div class="field"><label for="frequency">¿Cada cuánto cobran?</label><select id="frequency" name="frequency"><option value="monthly">Cada mes</option><option value="weekly">Cada semana</option><option value="custom">Cada cierto número de días</option></select></div><div class="field" id="interval-field" hidden><label for="interval">Días entre turnos</label><input id="interval" name="interval" type="number" min="1" max="365" value="7"></div><div class="field"><label for="start">Primera fecha de cobro</label><input id="start" name="start" type="date" value="${localNow().slice(0,10)}" required></div><label class="check-label field full"><input type="checkbox" required>El grupo acordó el aporte, las fechas y la multa. Todos aportan hasta el final.</label></div><p class="form-error"></p><div class="form-actions"><button class="button primary" type="submit">Crear grupo ${icon('arrow')}</button></div></form>`);}
function submitGroup(form){const f=Object.fromEntries(new FormData(form));const names=f.assignment==='manual'?parseOrderedNames(f.names):parseNames(f.names);if(names.length<2||names.length>100)throw Error('Ingresa entre 2 y 100 participantes.');if(names.some(n=>n.length>100))throw Error('Cada nombre debe tener hasta 100 caracteres.');if(new Set(names.map(normalizeName)).size!==names.length)throw Error('Hay nombres repetidos. Añade apellidos para distinguirlos.');if(!f.name.trim()||!f.admin.trim()||!f.fundDestination.trim())throw Error('Completa el nombre del grupo, administrador y destino del fondo.');const amount=cents(f.amount);if(!amount)throw Error('El aporte debe ser mayor a cero.');const interval=Number(f.interval);if(!Number.isInteger(interval)||interval<1||interval>365)throw Error('Revisa los días entre turnos.');const dates=schedule(f.start,f.frequency,names.length,interval);if(dates.some(d=>d>'2100-12-31')||f.start<'2000-01-01')throw Error('Usa fechas entre 2000 y 2100.');const g={id:uid(),name:f.name.trim(),admin:f.admin.trim(),amount,fine:cents(f.fine),frequency:f.frequency,interval,time:f.time,fundDestination:f.fundDestination.trim(),agreement:f.agreement.trim(),people:names.map(name=>({id:uid(),name})),periods:dates.map(date=>({id:uid(),date,time:f.time,person:null,payout:null})),order:[],pending:null,fineMode:'manual',fineAssessments:[],payments:[],waivers:[],fundUses:[],audit:[],createdAt:new Date().toISOString()};audit(g,'Grupo creado. Aporte, participantes, calendario y reglas acordados.');if(f.assignment==='manual'){applyManualOrder(g,g.people.map(p=>p.id));audit(g,'Orden de la lista acordado por el grupo, registrado sin sorteo: '+g.people.map((p,i)=>`${i+1}. ${p.name} (${g.periods[i].date})`).join('; ')+'.');}if(change(()=>{db.groups.push(g);db.active=g.id;view='overview';periodId=null;},g.assignment==='manual'?'Orden registrado. El calendario ya está listo.':'Tu pasanaku está listo. Ya puedes sortear los turnos.'))$('modal').close();}
function paymentModal(personId,turnId){quickAction('quick-pay',personId,turnId);}
function quickAction(task,personId,turnId,recordId){
 const g=group();
 change(()=>{
  const p=g.periods.find(r=>r.id===turnId)||selected(g),who=person(g,personId);
  if(task==='quick-undo'){const record=g.payments.find(r=>r.id===recordId);undoPayment(g,record);audit(g,`Pago deshecho para ${person(g,record.person).name}, turno ${g.periods.findIndex(p=>p.id===record.period)+1}.`);return;}
  if(!who)throw Error('Participante no encontrado.');
  if(task==='quick-fine'){assessFine(g,p,who);audit(g,`Multa marcada para ${who.name}: ${money(g.fine)}. Turno ${g.periods.indexOf(p)+1}.`);}
  else if(task==='quick-fine-remove'){const o=obligation(g,p,who),r=g.fineAssessments.find(r=>r.period===p.id&&r.person===who.id&&!r.voided);if(!r||o.finePaid)throw Error('No puedes quitar una multa cobrada. Deshaz primero el cobro.');r.voided={at:new Date().toISOString(),reason:'Corrección del administrador'};audit(g,`Multa quitada a ${who.name}, turno ${g.periods.indexOf(p)+1}.`);}
  else {const r=quickPayment(g,p,who,task==='quick-fine-pay'?'fine':'principal');audit(g,`${r.fine?'Multa cobrada':'Pago registrado'} de ${who.name}: ${money(r.principal+r.fine)}. Turno ${g.periods.indexOf(p)+1}.`);}
 },task==='quick-undo'?'Pago deshecho.':task==='quick-fine'?'Multa marcada.':task==='quick-fine-remove'?'Multa quitada.':task==='quick-fine-pay'?'Multa pagada.':'Pago registrado.');
}
function reasonModal(title,description,action,data){showModal(`<h2>${title}</h2><p>${description}</p><form id="reason-form" data-task="${action}" ${data}><div class="field"><label for="reason">Motivo del cambio</label><textarea id="reason" name="reason" required minlength="5" maxlength="300" placeholder="Explica el motivo para que quede en el historial."></textarea></div><p class="form-error" id="reason-error"></p><div class="form-actions"><button class="button primary" type="submit">Confirmar registro</button></div></form>`);}
function submitReason(form){const reason=new FormData(form).get('reason').trim();if(reason.length<5)throw Error('Escribe un motivo de al menos 5 caracteres.');const g=group();const task=form.dataset.task;if(change(()=>{if(task==='void'){const r=g.payments.find(r=>r.id===form.dataset.id),p=g.periods.find(p=>p.id===r.period);if(r.voided)throw Error('El registro ya está anulado.');if(p.payout&&r.principal)throw Error('El fondo ya fue entregado. No se puede anular un aporte que respalda esa entrega.');if(r.fine&&groupTotals(g).finePaid-r.fine<groupTotals(g).fineUsed)throw Error('Este dinero del fondo de multas ya se utilizó.');r.voided={at:new Date().toISOString(),reason};audit(g,`Anulado pago de ${person(g,r.person).name}, turno ${g.periods.indexOf(p)+1}: ${reason}`);}else if(task==='waive'){const p=g.periods.find(p=>p.id===form.dataset.period),who=person(g,form.dataset.person),o=obligation(g,p,who);if(o.finePaid||o.waiver||!o.fine)throw Error('Esta multa ya fue pagada, condonada o no corresponde.');g.waivers.push({id:uid(),period:p.id,person:who.id,reason,at:new Date().toISOString()});audit(g,`Multa condonada a ${who.name}, turno ${g.periods.indexOf(p)+1}: ${reason}`);}},'Cambio registrado en el historial.'))$('modal').close();}
function payoutModal(){const g=group(),p=selected(g),amount=validatePayout(g,p);if(localNow().slice(0,10)<p.date)throw Error('La fecha de entrega de este turno todavía no llegó.');showModal(`<div class="result"><div class="result-icon">${icon('wallet')}</div><h2>¿Ya entregaste el fondo?</h2><p>${escape(person(g,p.person).name)} · ${money(amount)}<br>Confirma después de entregar el dinero.</p>${button('Sí, marcar como entregado','quick-delivery')}</div>`);}
function fundModal(){const g=group(),tot=groupTotals(g);showModal(`<h2>Registrar uso de las multas</h2><p>Fondo disponible: <strong>${money(tot.finePaid-tot.fineUsed)}</strong><br>Destino acordado: ${escape(g.fundDestination)}</p><form id="fund-form"><div class="field"><label for="fund-amount">Monto utilizado (Bs)</label><input id="fund-amount" name="amount" type="number" min="0.01" step="0.01" required></div><br><div class="field"><label for="fund-reason">Destino, beneficiarios y motivo</label><textarea id="fund-reason" name="reason" minlength="5" maxlength="300" required></textarea></div><br><label class="check-label"><input type="checkbox" required>El grupo acordó este uso y el dinero ya se entregó o utilizó.</label><p class="form-error" id="fund-error"></p><div class="form-actions"><button type="submit" class="button primary">Guardar uso del fondo</button></div></form>`);}
function drawWheel(g,rotation=0){const canvas=$('wheel');if(!canvas)return;const ctx=canvas.getContext('2d');const remaining=g.people.filter(p=>!g.order.includes(p.id));const entries=remaining.length?remaining.map(p=>p.name):['Todos tienen','su turno','Cuentas claras','Ahorro juntos','Confianza','Pasanaku'];const colors=['#afd1ba','#e9c18c','#b4c8df','#c5b6da','#dfab9f','#d2d9a5','#91c4bd','#e3c9d1'];const arc=2*Math.PI/entries.length;ctx.clearRect(0,0,900,900);ctx.save();ctx.translate(450,450);ctx.rotate(rotation);entries.forEach((name,i)=>{const start=i*arc-Math.PI/2;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,450,start,start+arc);ctx.closePath();ctx.fillStyle=colors[i%colors.length];ctx.fill();ctx.strokeStyle='#ffffff80';ctx.lineWidth=2;ctx.stroke();if(entries.length>50)return;ctx.save();ctx.rotate(start+arc/2);ctx.font=`600 ${entries.length>20?16:entries.length>12?20:27}px Arial`;ctx.fillStyle='#2a4e3b';ctx.textAlign='right';ctx.textBaseline='middle';let label=name;while(ctx.measureText(label).width>290&&label.length>1)label=label.slice(0,-1);if(label!==name)label=label.slice(0,-1)+'…';ctx.fillText(label,405,0);ctx.restore();});ctx.restore();}
function spin(){const g=group();if(spinning||g.pending)return;const remaining=g.people.filter(p=>!g.order.includes(p.id));if(!remaining.length)return;const index=chooseIndex(remaining,g.order.length);if(!change(()=>{g.pending={person:remaining[index].id,at:new Date().toISOString()};audit(g,`Resultado del turno ${g.order.length+1} fijado: ${remaining[index].name}. Pendiente de aceptar.`);}))return;spinning=true;render();const target=(2*Math.PI-(index+.5)*2*Math.PI/remaining.length)%(2*Math.PI),from=angle,to=from+10*Math.PI+((target-from%(2*Math.PI)+2*Math.PI)%(2*Math.PI));const start=performance.now(),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?0:3400;function frame(now){const t=duration?Math.min((now-start)/duration,1):1;angle=from+(to-from)*(1-(1-t)**4);drawWheel(g,angle);if(t<1)requestAnimationFrame(frame);else{spinning=false;angle=target;render();showPending();}}requestAnimationFrame(frame);}
function showPending(){const g=group();if(!g?.pending)return;const p=g.periods[g.order.length];showModal(`<div class="result"><div class="result-icon">✦</div><div class="eyebrow">TURNO ${g.order.length+1} · ${escape(formatDate(p.date))}</div><h2>${escape(person(g,g.pending.person).name)}</h2><p>Este resultado ya está guardado. Al aceptar se asignará la fecha y el nombre saldrá de la ruleta.</p>${button('Aceptar y asignar turno '+icon('arrow'),'accept','primary')}</div>`,true);}
function downloadBackup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pasanaku-respaldo-${localNow().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validateBackup(data){if(!data||data.schema!==2||!Array.isArray(data.groups)||data.groups.length>200)throw Error('El archivo no es un respaldo compatible.');const ids=new Set();for(const g of data.groups){if(!validId(g.id)||ids.has(g.id))throw Error('Identificadores de grupo inválidos.');ids.add(g.id);for(const k of ['name','admin','time','fundDestination','agreement','createdAt'])if(typeof g[k]!=='string')throw Error('Faltan acuerdos del grupo.');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(g.time))throw Error('Hora límite inválida.');if(!Number.isSafeInteger(g.amount)||g.amount<=0||g.amount>100000000||!Number.isSafeInteger(g.fine)||g.fine<0||g.fine>100000000)throw Error('Los montos del respaldo no son válidos.');if(!['monthly','weekly','custom'].includes(g.frequency)||!Number.isInteger(g.interval)||g.interval<1||g.interval>365)throw Error('Frecuencia inválida.');for(const k of ['people','periods','payments','order','waivers','fundUses','audit'])if(!Array.isArray(g[k]))throw Error('El respaldo está incompleto.');if(g.people.length<2||g.people.length>100||g.periods.length!==g.people.length)throw Error('Participantes o calendario inválidos.');const people=new Set(g.people.map(p=>p.id)),periods=new Set(g.periods.map(p=>p.id));if(people.size!==g.people.length||periods.size!==g.periods.length||g.people.some(p=>!validId(p.id)||typeof p.name!=='string'||!p.name.trim()))throw Error('Participantes inválidos.');if(g.assignment!==undefined&&!['draw','manual'].includes(g.assignment))throw Error('Modo de asignación inválido.');if(g.assignment==='manual'&&(g.order.length!==g.people.length||g.pending))throw Error('El orden acordado está incompleto.');if(new Set(g.order).size!==g.order.length||g.order.some(id=>!people.has(id)))throw Error('Orden de sorteo inválido.');if(g.pending&&(!people.has(g.pending.person)||g.order.includes(g.pending.person)))throw Error('Resultado pendiente inválido.');for(const [i,p]of g.periods.entries()){if(!validId(p.id)||!Number.isFinite(deadline(p))||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(p.time)||p.person!==(g.order[i]||null))throw Error('Turnos inválidos.');if(p.payout&&(!Number.isFinite(Date.parse(p.payout.at))||p.payout.amount!==g.amount*g.people.length))throw Error('Desembolso inválido.');}if(g.fineMode!==undefined&&g.fineMode!=='manual')throw Error('Modo de multas inválido.');if(g.fineMode==='manual'){if(!Array.isArray(g.fineAssessments))throw Error('Faltan las multas registradas.');const active=new Set(),fineIds=new Set();for(const f of g.fineAssessments){const key=f.period+'|'+f.person;if(!validId(f.id)||fineIds.has(f.id)||!people.has(f.person)||!periods.has(f.period)||!Number.isSafeInteger(f.amount)||f.amount<=0||f.amount>100000000||!Number.isFinite(Date.parse(f.at)))throw Error('Multa registrada inválida.');fineIds.add(f.id);if(!f.voided){if(active.has(key))throw Error('Multas duplicadas.');active.add(key);}}}for(const r of g.payments){if(!validId(r.id)||!people.has(r.person)||!periods.has(r.period)||!Number.isFinite(Date.parse(r.at))||!Number.isSafeInteger(r.principal)||r.principal<0||!Number.isSafeInteger(r.fine)||r.fine<0||typeof r.method!=='string'||typeof r.reference!=='string')throw Error('Registro de pago inválido.');}if(new Set(g.payments.map(r=>r.id)).size!==g.payments.length)throw Error('Pagos duplicados.');for(const w of g.waivers)if(!validId(w.id)||!people.has(w.person)||!periods.has(w.period)||typeof w.reason!=='string')throw Error('Condonación inválida.');for(const r of g.fundUses)if(!validId(r.id)||!Number.isSafeInteger(r.amount)||r.amount<=0||typeof r.reason!=='string'||!Number.isFinite(Date.parse(r.at)))throw Error('Uso de fondo inválido.');for(const a of g.audit)if(!validId(a.id)||typeof a.text!=='string'||!Number.isFinite(Date.parse(a.at)))throw Error('Historial inválido.');for(const p of g.periods){for(const who of g.people){const o=obligation(g,p,who);if(o.principal>g.amount||o.finePaid>o.fine)throw Error('Saldos de pagos inconsistentes.');}if(p.payout&&periodTotals(g,p).owed)throw Error('Hay una entrega con aportes faltantes.');}const t=groupTotals(g);if(t.finePaid<t.fineUsed)throw Error('El fondo de multas tiene saldo negativo.');}if((data.groups.length&&!ids.has(data.active))||(!data.groups.length&&data.active!==null))throw Error('El grupo activo no existe.');return true;}
async function cloudLoad(){const remote=await sync.previewRemote(),data=remote.data;if(!data){notify('La cuenta está vacía. El próximo cambio se guardará automáticamente.');return;}validateBackup(data);showModal(`<h2>Revisar la copia de Supabase</h2><p>Contiene ${data.groups.length} grupos. Cargarla reemplazará los datos de este dispositivo. Descarga primero una copia si tienes cambios locales pendientes.</p><div class="actions">${button('Descargar copia local','backup','secondary')}${button('Usar copia de Supabase','cloud-use')}</div>`);pendingCloud=remote;}
let pendingImport=null,pendingCloud=null;
document.addEventListener('click',async event=>{const route=event.target.closest('[data-view]');if(route){if(spinning)return notify('Espera a que termine el giro.');view=route.dataset.view;search='';render();window.scrollTo({top:0});return;}const control=event.target.closest('[data-action]');if(!control)return;const task=control.dataset.action,g=group();try{if(task.startsWith('quick-')&&task!=='quick-delivery')quickAction(task,control.dataset.person,control.dataset.period,control.dataset.id);if(task==='quick-delivery'){if(change(()=>{const p=selected(g),amount=validatePayout(g,p);if(localNow().slice(0,10)<p.date)throw Error('La fecha del turno todavía no llegó.');p.payout={amount,at:new Date().toISOString(),method:'Sin especificar',reference:'Entrega confirmada por el administrador',recordedAt:new Date().toISOString()};audit(g,`Fondo entregado a ${person(g,p.person).name}: ${money(amount)}. Turno ${g.periods.indexOf(p)+1}.`);},'Entrega registrada.'))$('modal').close();}if(task==='create')createGroup();if(task==='turn'){periodId=control.dataset.id;view='payments';render();}if(task==='payment')paymentModal(control.dataset.person,control.dataset.period);if(task==='manual-order')manualOrderModal();if(task==='edit-manual-order'){const order=JSON.parse(new FormData($('confirm-order-form')).get('order'));manualOrderModal();$('manual-names').value=order.map(id=>person(g,id).name).join('\n');}if(task==='spin')spin();if(task==='pending')showPending();if(task==='accept'){if(g.pending&&change(()=>{const p=g.periods[g.order.length];p.person=g.pending.person;g.order.push(g.pending.person);audit(g,`Turno ${g.order.length} aceptado para ${person(g,g.pending.person).name}, fecha ${p.date}.`);g.pending=null;angle=0;},'Turno asignado.'))$('modal').close();}if(task==='report-all')openReport(g);if(task==='report-period')openReport(g,selected(g).id);if(task==='payout')payoutModal();if(task==='void-payment')reasonModal('Anular un registro','El movimiento seguirá visible. Sus montos dejarán de contar en el saldo. Si ya respaldó una entrega, no se podrá anular.','void',`data-id="${control.dataset.id}"`);if(task==='waive')reasonModal('Condonar una multa','Registra el acuerdo que justifica perdonar esta multa. Solo se permiten multas que aún no fueron cobradas.','waive',`data-person="${control.dataset.person}" data-period="${control.dataset.period}"`);if(task==='fund-use')fundModal();if(task==='backup')downloadBackup();if(task==='import')$('import-file').click();if(task==='restore'){if(pendingImport&&change(()=>{db=structuredClone(pendingImport);periodId=null;},'Datos cargados. Se guardarán automáticamente al conectar.')){pendingImport=null;$('modal').close();}}if(task==='cloud-use'){if(pendingCloud){sync.useRemote(pendingCloud);pendingCloud=null;$('modal').close();notify('Copia de Supabase recuperada.');}}if(task==='logout'){logout();sync.connectionChanged();render();notify('Sesión cerrada. La copia local sigue en este navegador.');}if(task==='cloud-probe'){control.disabled=true;await probeConnection();notify('Supabase responde correctamente. Inicia sesión para acceder a tus datos privados.');}if(task==='cloud-load'){control.disabled=true;await cloudLoad();}if(task==='cloud-push'||task==='sync-retry'){if(['conflict','auth'].includes(sync.status().kind)){view='settings';render();}else{control.disabled=true;await sync.reconcile();}}if(task==='delete-group'){showModal(`<h2>Eliminar grupo sin iniciar</h2><p>Se eliminará ${escape(g.name)} de esta copia. No contiene sorteos ni movimientos.</p>${button('Confirmar eliminación','delete-confirm','danger')}`);}if(task==='delete-confirm'){if(g.order.length||g.pending||g.payments.length||g.fundUses.length||g.fineAssessments?.length)throw Error('El grupo ya comenzó.');if(change(()=>{db.groups=db.groups.filter(x=>x.id!==g.id);db.active=db.groups[0]?.id||null;},'Grupo sin iniciar eliminado.'))$('modal').close();}}catch(error){notify(error.message);}finally{if(control.isConnected)control.disabled=false;}});
document.addEventListener('change',event=>{if(event.target.id==='frequency')$('interval-field').hidden=event.target.value!=='custom';if(event.target.id==='group-select'){if(spinning)return;change(()=>{db.active=event.target.value;periodId=null;});if(group()?.pending)showPending();}if(event.target.id==='period-select'){periodId=event.target.value;render();}});
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;$('payment-rows').innerHTML=paymentRows(group(),selected(group()));}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,submit=form.querySelector('[type="submit"]');const errorNode=form.querySelector('.form-error');if(errorNode)errorNode.textContent='';if(submit)submit.disabled=true;try{if(form.id==='group-form')submitGroup(form);if(form.id==='manual-order-form')previewManualOrder(form);if(form.id==='confirm-order-form')submitManualOrder(form);if(form.id==='reason-form')submitReason(form);if(form.id==='payout-form'){const g=group(),p=g.periods.find(p=>p.id===form.dataset.period),f=Object.fromEntries(new FormData(form)),at=new Date(f.at+':00-04:00').toISOString();if(Date.parse(at)>Date.now()+60000)throw Error('La entrega no puede estar en el futuro.');const amount=validatePayout(g,p);if(Date.parse(at)<Date.parse(p.date+'T00:00:00-04:00'))throw Error('La entrega no puede ser anterior a la fecha del turno.');const lastPayment=Math.max(...g.payments.filter(r=>!r.voided&&r.period===p.id&&r.principal).map(r=>Date.parse(r.at)));if(Date.parse(at)<lastPayment)throw Error('La entrega no puede ser anterior al último aporte recibido.');if(change(()=>{p.payout={amount,at,method:f.method,reference:f.reference.trim(),recordedAt:new Date().toISOString()};audit(g,`Entrega de ${money(amount)} registrada para ${person(g,p.person).name}. Turno ${g.periods.indexOf(p)+1}. Referencia: ${f.reference.trim()}`);},'Entrega del fondo registrada.'))$('modal').close();}if(form.id==='fund-form'){const g=group(),f=Object.fromEntries(new FormData(form)),amount=cents(f.amount),tot=groupTotals(g);if(!amount||amount>tot.finePaid-tot.fineUsed)throw Error('El monto supera el fondo disponible.');if(f.reason.trim().length<5)throw Error('Detalla el destino del dinero.');if(change(()=>{g.fundUses.push({id:uid(),amount,reason:f.reason.trim(),at:new Date().toISOString()});audit(g,`Uso de multas: ${money(amount)}. ${f.reason.trim()}`);},'Uso del fondo registrado.'))$('modal').close();}if(form.id==='config-form'){configure($('cloud-url').value,$('cloud-key').value);sync.connectionChanged();render();notify('Configuración guardada. Inicia sesión.');}if(form.id==='login-form'){await login($('email').value,$('password').value);sync.connectionChanged();render();notify('Sesión iniciada. Comprobando tus datos en Supabase…');}}catch(error){if(errorNode)errorNode.textContent=error.message;else notify(error.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
$('import-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('El respaldo supera los 10 MB permitidos.');const data=JSON.parse(await file.text());validateBackup(data);pendingImport=data;showModal(`<h2>Restaurar respaldo</h2><p>El archivo contiene ${data.groups.length} grupos. Reemplazará los datos locales actuales. Puedes descargar una copia antes de continuar.</p><div class="actions">${button('Respaldar datos actuales','backup','secondary')}${button('Restaurar estos datos','restore')}</div>`);}catch(error){notify('No se pudo cargar: '+error.message);}event.target.value='';});
function updateSyncUI() {
 const state=sync?.status()||{kind:'checking',message:'Comprobando guardado…'};
 if($('sync-label')) $('sync-label').textContent=state.message;
 if($('sync-banner')) $('sync-banner').dataset.state=state.kind;
 if($('sync-retry')) {$('sync-retry').hidden=!['error','offline','conflict','auth'].includes(state.kind);$('sync-retry').textContent=state.kind==='conflict'?'Revisar copias':state.kind==='auth'?'Iniciar sesión':'Reintentar';}
 if($('sync-detail')) $('sync-detail').textContent=state.message;
 if($('cloud-status')) $('cloud-status').textContent=state.message;
 if($('connection-label')) $('connection-label').textContent=state.kind==='saved'?'Guardado en Supabase':state.kind==='saving'?'Guardando…':cloudInfo().connected?'Guardado automático':'Guardado en este dispositivo';
}
sync=createAutoSync({
 initial:syncDoc,
 upgrade:data=>{for(const g of data.groups)enableManualFines(g);return data;},
 store:doc=>{const latest=localStorage.getItem(deviceKey);if(latest!==deviceRaw)throw Error('Otra pestaña cambió los datos. Recarga antes de continuar.');const raw=JSON.stringify(doc);localStorage.setItem(deviceKey,raw);deviceRaw=raw;},
 cloud:{scope:()=>cloudInfo().scope,read:readRemote,write:writeRemote},
 validate:validateBackup,
 onData:data=>{db=data;periodId=null;render();if(group()?.pending&&!$('modal').open)showPending();},
 onState:updateSyncUI,
 canReplace:()=>!storageProblem&&!$('modal').open&&!spinning,
 online:()=>navigator.onLine
});
window.addEventListener('storage',event=>{if([deviceKey,storageKey].includes(event.key)&&event.newValue){tabStale=true;sync.dispose();showModal('<h2>Los datos cambiaron en otra pestaña</h2><p>Recarga esta página para usar la copia más reciente antes de registrar otro movimiento.</p><button class="button primary" onclick="location.reload()">Recargar datos</button>',true);}});
window.addEventListener('online',()=>{if(!storageProblem)void sync.reconcile();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!storageProblem)void sync.reconcile();});
window.addEventListener('beforeunload',event=>{const doc=sync.snapshot();if(doc.dirty&&(doc.owner||cloudInfo().connected)){event.preventDefault();event.returnValue='';}});
setInterval(()=>{if(!document.hidden&&cloudInfo().connected&&!storageProblem&&!tabStale)void sync.reconcile();},30000);
render();if(group()?.pending)showPending();if(!storageProblem)void sync.reconcile();
setInterval(()=>{if(!$('modal').open&&!spinning&&['overview','payments','fines','people'].includes(view)&&!document.activeElement?.matches('input,select,textarea'))render();},60000);
